<template>
 <ThemePage>
  <view class="member-coupons" :data-member-coupons-owner="s.loggedIn?auth.uid:0" :data-member-coupons-phase="s.phase" :data-member-coupon-pending="s.pendingIssue" :data-member-claimed-coupon="s.confirmed?.id||0">
   <view v-if="!s.loggedIn" class="state"><view>登录后领取会员优惠券</view><button class="brown-button" @tap="s.login">去登录</button></view>
   <template v-else>
    <view class="toolbar"><button :disabled="s.loading||s.busy" @tap="s.load(false)">刷新列表</button><button :disabled="s.busy" @tap="s.wallet">我的优惠券 <text>›</text></button></view>
