      <view class="coupon-item" :class="{disabled:row.owned&&!s.usable(row.owned)}">
       <view class="money"><view><text v-if="row.benefitType===1" class="symbol">￥</text><text class="number">{{s.amount(row.value,row.benefitType)}}</text><text v-if="row.benefitType===2" class="symbol">折</text></view><view class="minimum">{{row.minimum==='0.00'?'无门槛券':'满'+row.minimum+'元可用'}}</view></view>
       <view class="text-wrap"><view class="coupon-text"><view class="coupon-title">{{row.title}}</view><view class="validity">{{s.validity(row)}}</view><button class="rule-button" :aria-label="row.rule?'查看'+row.title+'用券规则':row.title+'适用范围'" :aria-expanded="s.expanded.includes(row.id)" :disabled="!row.rule||s.busy" @tap="s.toggleRule(row.id)">{{s.scope(row.scopeType)}}优惠券<text v-if="row.rule">丨查看用券规则 {{s.expanded.includes(row.id)?'⌃':'⌄'}}</text></button></view>
        <button v-if="row.owned" class="claim-button" :aria-label="s.status(row.owned)+row.title" :disabled="s.busy||s.loading||!s.usable(row.owned)" @tap="s.useCoupon(row.owned.id)">{{s.status(row.owned)}}</button>
        <button v-else class="claim-button" :aria-label="'领取'+row.title" :disabled="!s.canClaim(row)" @tap="s.claim(row.id)">{{s.busy&&s.pendingIssue===row.id?'领取中…':row.claimable?'立即领取':'暂不可领'}}</button>
       </view>
      </view>
      <view v-if="!row.owned&&!row.claimable" class="claim-reason">{{row.reason}}</view>
      <view v-if="row.rule&&s.expanded.includes(row.id)" class="rules" :data-member-coupon-rules="row.id">{{row.rule}}</view>
     </view>
    </view>
    <view v-if="!s.rows.length&&!s.loading&&!s.error" class="empty"><image src="/static/membership/no-coupons.gif" mode="aspectFit"/><view>暂无优惠券，去看点别的吧～</view><button @tap="s.membership">返回会员首页</button></view>
    <button v-if="s.rows.length&&!s.finished" class="load-more" :disabled="s.loading||s.busy" @tap="s.load(true)">加载更多会员优惠券</button>
    <view v-else-if="s.rows.length&&!s.loading" class="list-end">已经到底了</view>
   </template>
  </view>
  <DiySuspendedNavigation />
 </ThemePage>
</template>
